CREATE TABLE compensation_proposal_revision(org_id TEXT NOT NULL,id TEXT NOT NULL,employee_id TEXT NOT NULL,proposal_id TEXT NOT NULL,payload_id TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN('draft','submitted','approved','rejected','withdrawn')),kind TEXT NOT NULL CHECK(kind IN('initial','adjustment','correction')),effective_date TEXT NOT NULL CHECK(length(effective_date)=10 AND date(effective_date,'+0 days') IS NOT NULL AND date(effective_date,'+0 days')=effective_date),actor_subject_id TEXT NOT NULL,before_term_id TEXT,revision INTEGER NOT NULL CHECK(revision>0),basis_revision INTEGER NOT NULL CHECK(basis_revision>=0),recorded_at INTEGER NOT NULL,PRIMARY KEY(org_id,id),UNIQUE(org_id,id,employee_id),UNIQUE(org_id,proposal_id,revision),UNIQUE(org_id,proposal_id,employee_id,id,revision),UNIQUE(org_id,proposal_id,employee_id,id,revision,status,kind,effective_date,basis_revision,payload_id),CHECK((kind='initial' AND before_term_id IS NULL) OR (kind='adjustment' AND before_term_id IS NOT NULL) OR (kind='correction' AND before_term_id IS NULL)),UNIQUE(org_id,proposal_id,employee_id,id),UNIQUE(org_id,proposal_id,employee_id,id,revision,status),FOREIGN KEY(org_id,proposal_id,employee_id) REFERENCES compensation_proposal(org_id,id,employee_id) DEFERRABLE INITIALLY DEFERRED,FOREIGN KEY(org_id,actor_subject_id) REFERENCES subject(org_id,id) DEFERRABLE INITIALLY DEFERRED,FOREIGN KEY(org_id,before_term_id,employee_id) REFERENCES compensation_terms_version(org_id,id,employee_id) DEFERRABLE INITIALLY DEFERRED,FOREIGN KEY(org_id,proposal_id,id,employee_id,payload_id) REFERENCES compensation_payload(org_id,proposal_id,proposal_revision_id,employee_id,id) DEFERRABLE INITIALLY DEFERRED) STRICT;
CREATE TABLE compensation_approval(org_id TEXT NOT NULL,id TEXT NOT NULL,employee_id TEXT NOT NULL,proposal_id TEXT NOT NULL,proposal_revision_id TEXT NOT NULL,approver_subject_id TEXT NOT NULL,author_subject_id TEXT NOT NULL,payload_id TEXT NOT NULL,proposal_revision INTEGER NOT NULL CHECK(proposal_revision>0),basis_revision INTEGER NOT NULL CHECK(basis_revision>=0),comp_revision INTEGER NOT NULL CHECK(comp_revision=basis_revision+1),recorded_at INTEGER NOT NULL,submitted_status TEXT NOT NULL DEFAULT 'submitted' CHECK(submitted_status='submitted'),PRIMARY KEY(org_id,id),UNIQUE(org_id,id,employee_id),UNIQUE(org_id,id,employee_id,proposal_id),UNIQUE(org_id,id,employee_id,proposal_id,proposal_revision_id,basis_revision),UNIQUE(org_id,proposal_revision_id),UNIQUE(org_id,employee_id,comp_revision),CHECK(approver_subject_id<>author_subject_id),FOREIGN KEY(org_id,proposal_id,employee_id,author_subject_id) REFERENCES compensation_proposal(org_id,id,employee_id,author_subject_id) DEFERRABLE INITIALLY DEFERRED,FOREIGN KEY(org_id,proposal_id,employee_id,proposal_revision_id,proposal_revision,submitted_status) REFERENCES compensation_proposal_revision(org_id,proposal_id,employee_id,id,revision,status) DEFERRABLE INITIALLY DEFERRED,FOREIGN KEY(org_id,approver_subject_id) REFERENCES subject(org_id,id) DEFERRABLE INITIALLY DEFERRED,FOREIGN KEY(org_id,id,employee_id,payload_id) REFERENCES compensation_payload(org_id,approval_id,employee_id,id) DEFERRABLE INITIALLY DEFERRED) STRICT;
CREATE TABLE compensation_event(org_id TEXT NOT NULL,id TEXT NOT NULL,employee_id TEXT NOT NULL,approval_id TEXT NOT NULL,kind TEXT NOT NULL CHECK(kind IN('initial','adjustment','correction_replacement','correction_reversal')),effective_date TEXT NOT NULL CHECK(length(effective_date)=10 AND date(effective_date,'+0 days') IS NOT NULL AND date(effective_date,'+0 days')=effective_date),member_key TEXT NOT NULL DEFAULT '',before_term_id TEXT,after_term_id TEXT,corrects_event_id TEXT,sequence INTEGER NOT NULL CHECK(sequence>0),correction_group_id TEXT,created_term_id TEXT GENERATED ALWAYS AS (CASE WHEN kind='correction_reversal' THEN NULL ELSE after_term_id END) STORED,PRIMARY KEY(org_id,id),UNIQUE(org_id,id,employee_id),UNIQUE(org_id,id,employee_id,approval_id),UNIQUE(org_id,id,employee_id,approval_id,effective_date),UNIQUE(org_id,id,employee_id,after_term_id),UNIQUE(org_id,id,employee_id,created_term_id),UNIQUE(org_id,employee_id,sequence),UNIQUE(org_id,approval_id,member_key),UNIQUE(org_id,corrects_event_id),CHECK(corrects_event_id IS NULL OR corrects_event_id<>id),CHECK(before_term_id IS NULL OR after_term_id IS NULL OR before_term_id<>after_term_id),CHECK((kind='initial' AND before_term_id IS NULL AND after_term_id IS NOT NULL AND corrects_event_id IS NULL AND member_key='' AND correction_group_id IS NULL) OR (kind='adjustment' AND before_term_id IS NOT NULL AND after_term_id IS NOT NULL AND corrects_event_id IS NULL AND member_key='' AND correction_group_id IS NULL) OR (kind='correction_replacement' AND after_term_id IS NOT NULL AND corrects_event_id IS NOT NULL AND length(member_key) BETWEEN 1 AND 32 AND member_key NOT GLOB '*[^a-z0-9_]*' AND correction_group_id IS NOT NULL AND correction_group_id=approval_id) OR (kind='correction_reversal' AND before_term_id IS NULL AND corrects_event_id IS NOT NULL AND length(member_key) BETWEEN 1 AND 32 AND member_key NOT GLOB '*[^a-z0-9_]*' AND correction_group_id IS NOT NULL AND correction_group_id=approval_id)),UNIQUE(org_id