CREATE TABLE compensation_terms_version(org_id TEXT NOT NULL,id TEXT NOT NULL,employee_id TEXT NOT NULL,event_id TEXT NOT NULL,approval_id TEXT NOT NULL,payload_id TEXT NOT NULL,effective_date TEXT NOT NULL CHECK(length(effective_date)=10 AND date(effective_date,'+0 days') IS NOT NULL AND date(effective_date,'+0 days')=effective_date),version_no INTEGER NOT NULL CHECK(version_no>0),PRIMARY KEY(org_id,id),UNIQUE(org_id,id,employee_id),UNIQUE(org_id,id,employee_id,event_id),UNIQUE(org_id,employee_id,version_no),UNIQUE(org_id,event_id),UNIQUE(org_id,id,event_id,employee_id),FOREIGN KEY(org_id,event_id,employee_id,approval_id,effective_date) REFERENCES compensation_event(org_id,id,employee_id,approval_id,effective_date) DEFERRABLE INITIALLY DEFERRED,FOREIGN KEY(org_id,event_id,employee_id,id) REFERENCES compensation_event(org_id,id,employee_id,created_term_id) DEFERRABLE INITIALLY DEFERRED,FOREIGN KEY(org_id,id,employee_id,payload_id) REFERENCES compensation_payload(org_id,term_id,employee_id,id) DEFERRABLE INITIALLY DEFERRED) STRICT;
CREATE TABLE compensation_payload(org_id TEXT NOT NULL,id TEXT NOT NULL,employee_id TEXT NOT NULL,record_id TEXT NOT NULL,version_id TEXT NOT NULL,object_kind TEXT NOT NULL CHECK(object_kind IN('compensation_proposal','compensation_terms','compensation_decision')),purpose TEXT NOT NULL CHECK(purpose='financial'),schema_type TEXT NOT NULL CHECK(schema_type IN('compensation.proposal.v1','compensation.terms.v1','compensation.decision.v1')),schema_version INTEGER NOT NULL CHECK(schema_version=1),format_version INTEGER NOT NULL CHECK(format_version=1),algorithm TEXT NOT NULL CHECK(algorithm='A256GCM-RANDOMNONCE'),dek_id TEXT NOT NULL,kek_id TEXT NOT NULL CHECK(length(kek_id)>0),kek_version INTEGER NOT NULL CHECK(kek_version>0),wrapped_dek BLOB NOT NULL CHECK(length(wrapped_dek)>0),sealed_bytes BLOB NOT NULL CHECK(length(sealed_bytes)>=28),created_at INTEGER NOT NULL,proposal_id TEXT,proposal_revision_id TEXT,term_id TEXT,approval_id TEXT,PRIMARY KEY(org_id,id),UNIQUE(org_id,id,employee_id),UNIQUE(org_id,proposal_id,proposal_revision_id,employee_id,id),UNIQUE(org_id,term_id,employee_id,id),UNIQUE(org_id,approval_id,employee_id,id),CHECK((object_kind='compensation_proposal' AND schema_type='compensation.proposal.v1' AND proposal_id IS NOT NULL AND proposal_revision_id IS NOT NULL AND term_id IS NULL AND approval_id IS NULL AND record_id=proposal_id AND version_id=proposal_revision_id AND id=proposal_revision_id) OR (object_kind='compensation_terms' AND schema_type='compensation.terms.v1' AND term_id IS NOT NULL AND proposal_id IS NULL AND proposal_revision_id IS NULL AND approval_id IS NULL AND record_id=term_id AND version_id=term_id AND id=term_id) OR (object_kind='compensation_decision' AND schema_type='compensation.decision.v1' AND approval_id IS NOT NULL AND proposal_id IS NULL AND proposal_revision_id IS NULL AND term_id IS NULL AND record_id=approval_id AND version_id=approval_id AND id=approval_id)),FOREIGN KEY(org_id,employee_id) REFERENCES employee(org_id,id) DEFERRABLE INITIALLY DEFERRED,FOREIGN KEY(org_id,proposal_revision_id,employee_id) REFERENCES compensation_proposal_revision(org_id,id,employee_id) DEFERRABLE INITIALLY DEFERRED,FOREIGN KEY(org_id,proposal_id,employee_id,proposal_revision_id) REFERENCES compensation_proposal_revision(org_id,proposal_id,employee_id,id) DEFERRABLE INITIALLY DEFERRED,FOREIGN KEY(org_id,term_id,employee_id) REFERENCES compensation_terms_version(org_id,id,employee_id) DEFERRABLE INITIALLY DEFERRED,FOREIGN KEY(org_id,approval_id,employee_id) REFERENCES compensation_approval(org_id,id,employee_id) DEFERRABLE INITIALLY DEFERRED) STRICT;
CREATE TABLE compensation_correction_group(org_id TEXT NOT NULL,id TEXT NOT NULL,employee_id TEXT NOT NULL,proposal_id TEXT NOT NULL,proposal_revision_id TEXT NOT NULL,approval_id TEXT NOT NULL,basis_revision INTEGER NOT NULL CHECK(basis_revision>=0),PRIMARY KEY(org_id,id),UNIQUE(org_id,id,employee_id),CHECK(id=approval_id),FOREIGN KEY(org_id,approval_id,employee_id,proposal_id,proposal_revision_id,basis_revision) REFERENCES compensation_approval(org_id,id,employee_id,proposal_id,proposal_revision_id,basis_revision) DEFERRABLE INITIALLY DEFERRED) STRICT;
CREATE TABLE compensation_correction_member(org_id TEXT NOT NULL,group_id TEXT NOT NULL,employee_id TEXT NOT NULL,member_key TEXT NOT NULL CHECK(length(member_key) BETWEEN 1 AND 32 AND member_key NOT GLOB '*[^a-z0-9_]*'),action TEXT NOT NULL CHECK(action IN('replace','reverse')),original_event_id TEXT NOT NULL,event_id TEXT NOT NULL,before_term_id TEXT,after_term_id TEXT,effective_date TEXT NOT NULL CHECK(length(effective_date)=10 AND date(effective_date,'+0 days') IS NOT NULL AND date(effective_date,'+0 days')=effective_date),event_kind TEXT GENERATED ALWAYS AS (CASE action WHEN 'replace' THEN 'correction_replacement' ELSE 'correction_reversal' END) STORED,PRIMARY KEY(org_id,group_id,member_key),UNIQUE(org_id,group_id,original_event_id),UNIQUE(org_id,event_id),UNIQUE(org_id,group_id,employee_id,member_key,event_id),CHECK((action='replace' AND after_term_id IS NOT NULL) OR (action='reverse' AND before_term_id IS NULL)),FOREIGN KEY(org_id,group_id,employee_id) REFERENCES compensation_correction_group(org_id,id,employee_id) DEFERRABLE INITIALLY DEFERRED,FOREIGN KEY(org_id,original_event_id,employee_id) REFERENCES compensation_event(org_id,id,employee_id) DEFERRABLE INITIALLY DEFERRED,FOREIGN KEY(org_id,event_id,employee_id,group_id,effective_date) REFERENCES compensation_event(org_id,id,employee_id,approval_id,effective_date) DEFERRABLE INITIALLY DEFERRED,FOREIGN KEY(org_id,before_term_id,employee_id) REFERENCES compensation_terms_version(org_id,id,employee_id) DEFERRABLE INITIALLY DEFERRED,FOREIGN KEY(org_id,event_id,employee_id,after_term_id) REFERENCES compensation_event(org_id,id,employee_id,after_term_id) DEFERRABLE INITIALLY DEFERRED,FOREIGN KEY(org_id,event_id,employee_id,group_id,member_key,original_event_id,event_kind,effective_date) REFERENCES compensation_event(org_id,id,employee_id,approval_id,member_key,corrects_event_id,kind,effective_date) DEFERRABLE INITIALLY DEFERRED) STRICT;
