CREATE TRIGGER compensation_proposal_transition BEFORE UPDATE ON compensation_proposal WHEN NEW.revision<>OLD.revision+1 OR NOT ((OLD.status='draft' AND NEW.status IN('draft','submitted','withdrawn')) OR (OLD.status='submitted' AND NEW.status IN('approved','rejected','withdrawn'))) OR (OLD.status='submitted' AND (NEW.kind IS NOT OLD.kind OR NEW.effective_date IS NOT OLD.effective_date OR NEW.before_term_id IS NOT OLD.before_term_id OR NEW.basis_revision IS NOT OLD.basis_revision)) BEGIN SELECT RAISE(ABORT,'invalid compensation transition'); END;
