CREATE TRIGGER compensation_aggregate_guard BEFORE UPDATE ON compensation_aggregate WHEN NEW.org_id IS NOT OLD.org_id OR NEW.employee_id IS NOT OLD.employee_id OR NEW.revision NOT IN(OLD.revision,OLD.revision+1) BEGIN SELECT RAISE(ABORT,'invalid compensation aggregate'); END;
